const cards=()=>Array.isArray(W.CARD_CATALOG)?W.CARD_CATALOG:[];
function membershipUniverse(){const m=new Map();for(const c of cards())for(const a of [...(Array.isArray(c?.archetypes)?c.archetypes:[]),c?.archetype].filter(Boolean)){const n=norm(a);if(n&&!m.has(n))m.set(n,String(a).trim())}try{for(const o of D.querySelectorAll('#arch option,#dbArchetype option')){const a=String(o.value||o.textContent||'').replace(/\s*[·(].*$/,'').trim();if(!a||/selecciona|todos los arquetipos|^otro$/i.test(a))continue;const n=norm(a);if(n&&!m.has(n))m.set(n,a)}}catch(_){}return m}
function alwaysTreated(c){const d=String(c?.desc||'');const out=[];const rx=/(?:this\s+card\s+is\s+|card\s+is\s+)?always\s+treated\s+as\s+(?:an?\s+)?[“"']([^”"']+)[”"']\s*(?:card)?/ig;let m;while((m=rx.exec(d)))out.push(m[1].trim());const rx2=/\(\s*this\s+card\s+is\s+always\s+treated\s+as\s+(?:an?\s+)?[“"']([^”"']+)[”"']\s*(?:card)?\s*\)/ig;while((m=rx2.exec(d)))out.push(m[1].trim());return [...new Set(out.filter(Boolean))]}
function quotedSupport(c,universe=membershipUniverse()){const d=String(c?.desc||''),out=[];const rx=/[“"']([^”"']{2,60})[”"']\s+(?:card|cards|monster|monsters|spell|spells|trap|traps)/ig;let m;while((m=rx.exec(d))){const n=norm(m[1]);if(universe.has(n))out.push(universe.get(n))}return [...new Set(out)]}
function enrichCard(c,universe){if(!c)return c;const direct=new Set([...(Array.isArray(c.archetypes)?c.archetypes:[]),c.archetype].filter(Boolean));for(const a of alwaysTreated(c)){const n=norm(a),canonical=universe.get(n)||a;direct.add(canonical)}const support=quotedSupport(c,universe).filter(a=>![...direct].some(x=>norm(x)===norm(a)));c.archetypes=[...direct];c.archetype=c.archetypes[0]||'';c.supportArchetypes=support;c.alwaysTreatedAs=alwaysTreated(c);return c}
function enrichAll(){const u=membershipUniverse();let multi=0,treated=0,support=0;for(const c of cards()){enrichCard(c,u);if((c.archetypes||[]).length>1)multi++;if((c.alwaysTreatedAs||[]).length)treated++;if((c.supportArchetypes||[]).length)support++}return{cards:cards().length,archetypes:membershipUniverse().size,multiMembership:multi,alwaysTreatedAs:treated,indirectSupport:support}}
function langField(c,lang){if(lang==='en')return c?.desc||c?.text||'';if(lang==='es')return c?.desc_es||c?.text_es||c?.spanish_desc||'';return c?.[`desc_${lang}`]||c?.[`text_${lang}`]||''}
function nameField(c,lang){if(lang==='en')return c?.name||'';return c?.[`name_${lang}`]||c?.[`localized_name_${lang}`]||''}
function localized(c,lang='es'){lang=LANGS.includes(lang)?lang:'es';const text=langField(c,lang),name=nameField(c,lang);if(text||name)return{name:name||c?.name||'Carta',text:text||c?.desc||'',language:lang,officialField:true,fallback:false};return{name:c?.name||'Carta',text:c?.desc||'',language:'source',requestedLanguage:lang,officialField:false,fallback:true,policy:'Fallback al texto fuente; no se presenta traducción automática de PSCT como oficial.'}}
function localizationCoverage(sampleLimit=0){const a=sampleLimit?cards().slice(0,Math.max(0,Number(sampleLimit)||0)):cards(),total=a.length||1,langs={};for(const l of LANGS){let names=0,texts=0;for(const c of a){if(nameField(c,l))names++;if(langField(c,l))texts++}langs[l]={nameFields:names,textFields:texts,namePct:Math.round(names/total*10000)/100,textPct:Math.round(texts/total*10000)/100}}return{version:VERSION,cards:a.length,languages:langs,policy:'Sólo campos localizados disponibles se consideran oficiales. El fallback conserva el texto fuente y nunca maquilla una traducción automática como PSCT oficial.'}}
function subArchetypes(){const names=[...membershipUniverse().values()],out=[];for(let i=0;i<names.length;i++)for(let j=0;j<names.length;j++){if(i===j)continue;const a=norm(names[i]),b=norm(names[j]);if(a.length>=4&&b.length>a.length&&b.includes(a))out.push({parent:names[i],child:names[j]})}const seen=new Set();return out.filter(x=>{const k=x.parent+'>'+x.child;if(seen.has(k))return false;seen.add(k);return true}).slice(0,500)}
