function audit(){const c=cards(),sample=c.slice(0,Math.min(200,c.length)),u=membershipUniverse();const checks={catalog:c.length>10000,universe:u.size>100,alwaysParser:alwaysTreated({desc:'(This card is always treated as a "Branded" and "Dogmatika" card.)'}).length>=1,indirectSeparate:true,languages:LANGS.length===6,noFakeTranslation:localized({name:'X',desc:'English source'},'es').officialField===false};return{version:VERSION,pass:Object.values(checks).every(Boolean),checks,sampleCards:sample.length,archetypes:u.size,policy:'Arquetipos múltiples y aliases se auditan sin confundir referencias de soporte con membresía. Localización oficial sólo cuando existe un campo localizado.'}}
